# old (English take) word index -> new (Urdu/Punjabi dialogue take) word index, line by line
LM=[(0, 8, 0, 8), (9, 18, 9, 18), (19, 27, 19, 27), (28, 33, 28, 35), (34, 40, 36, 43), (41, 48, 44, 55), (49, 52, 56, 58), (53, 58, 59, 64), (59, 64, 65, 70), (65, 70, 71, 76), (71, 76, 77, 82), (77, 79, 83, 85), (80, 83, 86, 89), (84, 88, 90, 100), (89, 90, 101, 104), (91, 93, 105, 108), (94, 96, 109, 111), (97, 99, 112, 114), (100, 106, 115, 125), (107, 115, 126, 141), (116, 121, 142, 149), (122, 127, 150, 155), (128, 133, 156, 161), (134, 140, 162, 168), (141, 146, 169, 177), (147, 149, 178, 181), (150, 152, 182, 185), (153, 155, 186, 188), (156, 158, 189, 193), (159, 164, 194, 199), (165, 172, 200, 207), (173, 176, 208, 211), (177, 184, 212, 221)]
def remap_words(Wn):
    out=[]
    for a,b,c,d in LM:
        for i in range(a,b+1): out.append(Wn[c if i==a else d if i==b else round(c+(i-a)*(d-c)/max(1,b-a))])
    return out
